# LinMinHaoChat PNS deploy script (run as Administrator in Workbench PowerShell)
$ErrorActionPreference = "Continue"

# [1] make sshd self-healing: auto-restart on failure
sc.exe failure sshd reset= 86400 actions= restart/5000/restart/10000/restart/30000
Restart-Service sshd -ErrorAction SilentlyContinue
Start-Sleep -Seconds 2
Get-Service sshd | Select-Object Name,Status | Format-Table -AutoSize

# [2] write dist files (base64 embedded)
$distRoot = "C:\opt\linminhao\app\dist"
$files = @(
  @{ path = "dist/routes/pns.js"; b64 = "" },
  @{ path = "dist/config.js"; b64 = "" },
  @{ path = "dist/app.js"; b64 = "" },
  @{ path = "dist/channels.js"; b64 = "" },
)
foreach ($f in $files) {
  $target = Join-Path $distRoot $f.path
  $dir = Split-Path $target -Parent
  if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  [IO.File]::WriteAllBytes($target, [Convert]::FromBase64String($f.b64))
  Write-Host ("written: " + $f.path + " (" + (Get-Item $target).Length + " bytes)")
}

# [3] install aliyun dypns SDK (npmmirror registry, China-friendly)
Set-Location "C:\opt\linminhao\app"
npm install @alicloud/dypnsapi20170525 --registry=https://registry.npmmirror.com --no-audit --no-fund 2>&1 | Select-Object -Last 3

# [4] restart node app (watchdog will keep it up)
Get-Process node -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
Start-Sleep -Seconds 3
Write-Host "node restarted, waiting for watchdog..."
